mapper.select:
SELECT invocation_id, task_id, user_public_id, thread_id, model_role, provider,
       model_key, credential_source, prompt_tokens, completion_tokens, latency_ms,
       status, error_type, estimated_cost, cost_status, cost_bearer, currency, occurred_at
FROM model_usage_records
WHERE user_public_id = #{userPublicId}

    AND occurred_at >= #{fromInclusive}


    AND occurred_at < #{toExclusive}

ORDER BY occurred_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
FROM model_usage_records
WHERE user_public_id = #{userPublicId}

    AND occurred_at >= #{fromInclusive}


    AND occurred_at < #{toExclusive}

SELECT COALESCE(SUM(COALESCE(prompt_tokens, 0) + COALESCE(completion_tokens, 0)), 0)
FROM model_usage_records
WHERE user_public_id = #{userPublicId}
